//! The account routes (the contract: docs/CLIENT_API.md "Accounts, settings and demigod personalities"; schemas:
//! `docs/schemas/account_*.schema.json`, generated by [`schemas`]).
//!
//! | Route | Auth | Answer |
//! |---|---|---|
//! | `GET /api/auth/config` | none | `{guest, google, moderation, name_guard}` |
//! | `POST /api/auth/guest` `{display_name, device_label?, claim_secret?}` | none | 201 `{session_token, session, account}` |
//! | `POST /api/auth/google/start` `{device_label?, display_name?}` | none, or a session to **link** | `{login_url, poll_token, expires, interval_ms}` (503 `google_not_configured`) |
//! | `GET /api/auth/google/callback?state&code` | Google's redirect | an HTML page for the browser |
//! | `POST /api/auth/poll` `{poll_token}` | none | `{status: pending}` / `{status: complete, session_token, session, account, created, linked}` / `{status: failed, error, detail}` |
//! | `POST /api/auth/logout` | session | 204 (this session is revoked) |
//! | `POST /api/auth/logout_all` | session | `{revoked}` |
//! | `GET /api/me` | session | `{account, session, sessions, google_configured}` |
//! | `DELETE /api/me` `{confirm}` | session | `{deleted, remains}` |
//! | `GET/PUT /api/me/settings` | session | `{settings}` |
//! | `GET /api/me/demigods` | session | `{left, right, limits}` |
//! | `GET/PUT /api/me/demigods/{left|right}` | session | the demigod, with the moderation answer on `PUT` |
//! | `GET /api/me/entitlements` | session | `{tier, entitlements, billing}` |
//! | `POST /api/game/bind` `{resume_token}` | session | `{bound, player_id, display_name, demigods}` |
//!
//! A session is `Authorization: Bearer <session_token>`. Every error is `{error: <code>, detail: <text>}` with the
//! HTTP status that fits (400 `invalid`, 401 `unauthorized`, 404 `not_found`, 409 `name_taken` / `name_lookalike` /
//! `name_conflict` / `identity_in_use`, 403 `profile_claimed`, 413 `too_large`, 422 `refused`, 429 `rate_limited`
//! with `Retry-After`, 503 `google_not_configured`). Every answer is `Cache-Control: no-store`. Nothing here logs a
//! token, a secret or an email.

use std::sync::Arc;

use fn7_agents::moderate::{self, Sheet, Verdict};
use fn7_profile::accounts::{Account, AccountError, DemigodDoc, DemigodRow, SessionInfo};
use fn7_profile::settings;
use serde::Deserialize;
use serde_json::{json, Value};
use theatre_server::axum::body::Bytes;
use theatre_server::axum::extract::{Path, Query, State};
use theatre_server::axum::http::{header, HeaderMap, HeaderValue, StatusCode};
use theatre_server::axum::response::{Html, IntoResponse, Response};
use theatre_server::axum::routing::{get, post};
use theatre_server::axum::{Json, Router};

use super::limiter::Class;
use super::{Accounts, Poll};

type St = State<Arc<Accounts>>;

/// Largest request body of the small routes, in bytes.
const MAX_BODY: usize = 8 * 1024;

pub fn router(accounts: Arc<Accounts>) -> Router {
    Router::new()
        .route("/api/auth/config", get(config))
        .route("/api/auth/guest", post(guest))
        .route("/api/auth/google/start", post(google_start))
        .route("/api/auth/google/callback", get(google_callback))
        .route("/api/auth/poll", post(poll))
        .route("/api/auth/logout", post(logout))
        .route("/api/auth/logout_all", post(logout_all))
        .route("/api/me", get(me).delete(delete_me))
        .route("/api/me/settings", get(get_settings).put(put_settings))
        .route("/api/me/demigods", get(get_demigods))
        .route("/api/me/demigods/{hand}", get(get_demigod).put(put_demigod))
        .route("/api/me/entitlements", get(entitlements))
        .route("/api/game/bind", post(bind))
        .with_state(accounts)
}

// ---- answers ----------------------------------------------------------------------------------------------------

fn finish(mut r: Response) -> Response {
    r.headers_mut().insert(header::CACHE_CONTROL, HeaderValue::from_static("no-store"));
    r
}

fn ok(v: Value) -> Response {
    finish(Json(v).into_response())
}

fn fail(status: StatusCode, code: &str, detail: impl Into<String>) -> Response {
    finish((status, Json(json!({ "error": code, "detail": detail.into() }))).into_response())
}

fn limited(wait: u64) -> Response {
    let mut r = fail(StatusCode::TOO_MANY_REQUESTS, "rate_limited", format!("too many requests: try again in {wait} s"));
    if let Ok(v) = HeaderValue::from_str(&wait.to_string()) {
        r.headers_mut().insert(header::RETRY_AFTER, v);
    }
    r
}

fn account_error(e: AccountError) -> Response {
    let status = match &e {
        AccountError::BadName | AccountError::Invalid(_) => StatusCode::BAD_REQUEST,
        AccountError::NameTaken | AccountError::NameLookalike(_) | AccountError::IdentityInUse => StatusCode::CONFLICT,
        AccountError::ProfileClaimed => StatusCode::FORBIDDEN,
        AccountError::NotFound => StatusCode::NOT_FOUND,
        AccountError::Store(_) => StatusCode::INTERNAL_SERVER_ERROR,
    };
    if let AccountError::Store(inner) = &e {
        tracing::warn!(error = %inner, "accounts: store error");
        return fail(status, "store", "the account store failed");
    }
    fail(status, e.code(), e.to_string())
}

/// Who is asking, for the address-keyed limits: the first hop of `X-Forwarded-For`, else `direct`.
fn client(h: &HeaderMap) -> String {
    h.get("x-forwarded-for")
        .and_then(|v| v.to_str().ok())
        .and_then(|v| v.split(',').next())
        .map(|v| v.trim().to_string())
        .filter(|v| !v.is_empty() && v.len() <= 64)
        .unwrap_or_else(|| "direct".into())
}

fn bearer(h: &HeaderMap) -> Option<String> {
    let v = h.get(header::AUTHORIZATION)?.to_str().ok()?;
    let t = v.strip_prefix("Bearer ").or_else(|| v.strip_prefix("bearer "))?.trim();
    (!t.is_empty()).then(|| t.to_string())
}

fn parse<T: for<'de> Deserialize<'de>>(body: &Bytes, max: usize) -> Result<T, Response> {
    if body.len() > max {
        return Err(fail(StatusCode::PAYLOAD_TOO_LARGE, "too_large", format!("the body is limited to {max} bytes")));
    }
    let slice: &[u8] = if body.is_empty() { b"{}" } else { body };
    serde_json::from_slice(slice).map_err(|e| fail(StatusCode::BAD_REQUEST, "invalid", format!("bad JSON body: {e}")))
}

/// Run a store call off the async runtime.
async fn blocking<T: Send + 'static>(st: &Arc<Accounts>, f: impl FnOnce(&Accounts) -> T + Send + 'static) -> Result<T, Response> {
    let st = st.clone();
    tokio::task::spawn_blocking(move || f(&st))
        .await
        .map_err(|_| fail(StatusCode::INTERNAL_SERVER_ERROR, "internal", "the request could not be completed"))
}

/// The session a request carries, or the 401.
async fn authed(st: &Arc<Accounts>, h: &HeaderMap) -> Result<(Account, SessionInfo), Response> {
    let unauthorized = || fail(StatusCode::UNAUTHORIZED, "unauthorized", "send a valid session as Authorization: Bearer <session_token>");
    let token = bearer(h).ok_or_else(unauthorized)?;
    match blocking(st, move |a| a.store().session_account(&token)).await? {
        Ok(Some(found)) => Ok(found),
        Ok(None) => Err(unauthorized()),
        Err(e) => Err(account_error(e)),
    }
}

async fn authed_limited(st: &Arc<Accounts>, h: &HeaderMap, class: Class) -> Result<(Account, SessionInfo), Response> {
    let found = authed(st, h).await?;
    st.limiter.check(class, &found.0.id).map_err(limited)?;
    Ok(found)
}

fn session_json(token: &str, info: &SessionInfo, account: &Account) -> Value {
    json!({ "session_token": token, "session": info, "account": account })
}

// ---- sign-in ----------------------------------------------------------------------------------------------------

async fn config(State(st): St) -> Response {
    ok(json!({
        "guest": true,
        "google": st.google_configured(),
        // The model that judges demigod sheets, or "rules" when no LLM is configured.
        "moderation": st.moderation_label(),
        "name_guard": st.guard_on(),
    }))
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct GuestBody {
    display_name: String,
    #[serde(default)]
    device_label: Option<String>,
    #[serde(default)]
    claim_secret: Option<String>,
}

async fn guest(State(st): St, h: HeaderMap, body: Bytes) -> Response {
    if let Err(w) = st.limiter.check(Class::Auth, &client(&h)) {
        return limited(w);
    }
    let b: GuestBody = match parse(&body, MAX_BODY) {
        Ok(b) => b,
        Err(r) => return r,
    };
    // A player's name goes through the rules pass (the lookalike check is the store's).
    let hits = moderate::rule_hits(&b.display_name);
    if !hits.is_empty() {
        return fail(StatusCode::UNPROCESSABLE_ENTITY, "refused", format!("that name is not allowed ({})", hits.join(", ")));
    }
    match blocking(&st, move |a| a.store().create_guest(&b.display_name, b.device_label.as_deref().unwrap_or(""), b.claim_secret.as_deref())).await {
        Ok(Ok((account, session))) => {
            tracing::info!(account = %account.id, "accounts: guest account created");
            finish((StatusCode::CREATED, Json(session_json(&session.token, &session.info, &account))).into_response())
        }
        Ok(Err(e)) => account_error(e),
        Err(r) => r,
    }
}

#[derive(Deserialize, Default)]
#[serde(deny_unknown_fields)]
struct StartBody {
    #[serde(default)]
    device_label: Option<String>,
    #[serde(default)]
    display_name: Option<String>,
}

async fn google_start(State(st): St, h: HeaderMap, body: Bytes) -> Response {
    if let Err(w) = st.limiter.check(Class::Auth, &client(&h)) {
        return limited(w);
    }
    if !st.google_configured() {
        return fail(StatusCode::SERVICE_UNAVAILABLE, "google_not_configured", "google sign-in is not configured on this server; guest accounts work");
    }
    let b: StartBody = match parse(&body, MAX_BODY) {
        Ok(b) => b,
        Err(r) => return r,
    };
    // A request that carries a session links Google to that account; a bad session is an error, not a silent sign-in.
    let link = if bearer(&h).is_some() {
        match authed(&st, &h).await {
            Ok((account, session)) => {
                if !account.guest {
                    return fail(StatusCode::CONFLICT, "already_linked", "this account already has a Google identity");
                }
                Some((account.id, session.id))
            }
            Err(r) => return r,
        }
    } else {
        None
    };
    let linking = link.is_some();
    match st.google_start(b.device_label.as_deref().unwrap_or(""), b.display_name.filter(|n| !n.trim().is_empty()), link) {
        Some((login_url, poll_token, expires)) => ok(json!({
            "login_url": login_url, "poll_token": poll_token, "expires": expires, "interval_ms": 2000, "linking": linking,
        })),
        None => fail(StatusCode::SERVICE_UNAVAILABLE, "google_not_configured", "google sign-in is not configured on this server; guest accounts work"),
    }
}

#[derive(Deserialize)]
struct CallbackQuery {
    #[serde(default)]
    state: Option<String>,
    #[serde(default)]
    code: Option<String>,
    #[serde(default)]
    error: Option<String>,
}

fn page(title: &str, text: &str) -> String {
    // Fixed strings only: nothing from the request is ever echoed into the page.
    format!(
        "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\
<title>Final Night 7</title><style>body{{font-family:system-ui,sans-serif;background:#111;color:#eee;display:flex;min-height:100vh;\
align-items:center;justify-content:center;margin:0}}main{{max-width:28rem;padding:2rem;text-align:center}}h1{{font-size:1.4rem}}\
p{{color:#bbb;line-height:1.5}}</style></head><body><main><h1>{title}</h1><p>{text}</p></main></body></html>"
    )
}

async fn google_callback(State(st): St, h: HeaderMap, Query(q): Query<CallbackQuery>) -> Response {
    if let Err(w) = st.limiter.check(Class::Auth, &client(&h)) {
        return limited(w);
    }
    let Some(state) = q.state.filter(|s| !s.is_empty() && s.len() <= 200) else {
        return finish((StatusCode::BAD_REQUEST, Html(page("Sign-in link not recognised", "Start the sign-in again from the game."))).into_response());
    };
    let (status, title, text) = match st.google_callback(&state, q.code.as_deref(), q.error.as_deref()).await {
        Ok(()) => (StatusCode::OK, "You are signed in", "You can close this tab and go back to Final Night 7."),
        Err((code, _)) => match code.as_str() {
            "unknown_state" | "state_already_used" => {
                (StatusCode::BAD_REQUEST, "Sign-in link not recognised", "This link is unknown, expired or already used. Start the sign-in again from the game.")
            }
            "google_not_configured" => (StatusCode::SERVICE_UNAVAILABLE, "Sign-in is not available", "Google sign-in is not configured on this server."),
            "name_taken" | "identity_in_use" | "invalid" => {
                (StatusCode::CONFLICT, "This Google account is already in use", "Go back to the game: it will tell you what to do next.")
            }
            _ => (StatusCode::BAD_GATEWAY, "Sign-in did not complete", "Google sign-in could not be verified. Go back to the game and try again."),
        },
    };
    finish((status, Html(page(title, text))).into_response())
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct PollBody {
    poll_token: String,
}

async fn poll(State(st): St, h: HeaderMap, body: Bytes) -> Response {
    if let Err(w) = st.limiter.check(Class::Poll, &client(&h)) {
        return limited(w);
    }
    let b: PollBody = match parse(&body, MAX_BODY) {
        Ok(b) => b,
        Err(r) => return r,
    };
    match blocking(&st, move |a| a.poll(&b.poll_token)).await {
        Ok(Poll::Pending) => ok(json!({ "status": "pending" })),
        Ok(Poll::Complete { session, account, created, linked }) => {
            let mut v = session_json(&session.token, &session.info, &account);
            v["status"] = "complete".into();
            v["created"] = created.into();
            v["linked"] = linked.into();
            ok(v)
        }
        Ok(Poll::Failed { code, message }) => ok(json!({ "status": "failed", "error": code, "detail": message })),
        Ok(Poll::Unknown) => fail(StatusCode::NOT_FOUND, "not_found", "unknown or expired poll token: start the sign-in again"),
        Err(r) => r,
    }
}

async fn logout(State(st): St, h: HeaderMap) -> Response {
    let (account, session) = match authed_limited(&st, &h, Class::Write).await {
        Ok(x) => x,
        Err(r) => return r,
    };
    match blocking(&st, move |a| a.store().revoke_session(&session.id)).await {
        Ok(Ok(_)) => {
            tracing::info!(account = %account.id, "accounts: logout");
            finish(StatusCode::NO_CONTENT.into_response())
        }
        Ok(Err(e)) => account_error(e),
        Err(r) => r,
    }
}

async fn logout_all(State(st): St, h: HeaderMap) -> Response {
    let (account, _) = match authed_limited(&st, &h, Class::Write).await {
        Ok(x) => x,
        Err(r) => return r,
    };
    let id = account.id.clone();
    match blocking(&st, move |a| a.store().revoke_all_sessions(&id)).await {
        Ok(Ok(n)) => {
            tracing::info!(account = %account.id, revoked = n, "accounts: logout everywhere");
            ok(json!({ "revoked": n }))
        }
        Ok(Err(e)) => account_error(e),
        Err(r) => r,
    }
}

// ---- the account ------------------------------------------------------------------------------------------------

async fn me(State(st): St, h: HeaderMap) -> Response {
    let (account, session) = match authed_limited(&st, &h, Class::Read).await {
        Ok(x) => x,
        Err(r) => return r,
    };
    let (id, sid) = (account.id.clone(), session.id.clone());
    match blocking(&st, move |a| a.store().sessions(&id, Some(&sid))).await {
        Ok(Ok(sessions)) => ok(json!({
            "account": account, "session": session, "sessions": sessions, "google_configured": st.google_configured(),
        })),
        Ok(Err(e)) => account_error(e),
        Err(r) => r,
    }
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct DeleteBody {
    confirm: String,
}

/// What a deletion cannot reach, said exactly (docs/ACCOUNTS.md "Deleting an account").
pub const REMAINS: [&str; 5] = [
    "match recordings (server-side JSONL files, admin access only): the display name you played under, your demigods' names and personality text as they were in those matches, and the orders you typed",
    "images already generated for your demigods (keyed by demigod name) in the media cache",
    "other players' history rows that mention your display name or your demigods' names (a champion's name, an elimination)",
    "the list of past matches (ids, dates, champions' names) without your own row",
    "a one-way hash of each profile name you held, kept so a rebuild from old recordings never restores your history",
];

async fn delete_me(State(st): St, h: HeaderMap, body: Bytes) -> Response {
    let (account, _) = match authed_limited(&st, &h, Class::Write).await {
        Ok(x) => x,
        Err(r) => return r,
    };
    let b: DeleteBody = match parse(&body, MAX_BODY) {
        Ok(b) => b,
        Err(r) => return r,
    };
    if fn7_profile::normalize_name(&b.confirm) != fn7_profile::normalize_name(&account.display_name) {
        return fail(StatusCode::BAD_REQUEST, "confirm_required", "send {\"confirm\": \"<your display name>\"} to delete the account");
    }
    let id = account.id.clone();
    match blocking(&st, move |a| a.store().delete_account(&id)).await {
        Ok(Ok(d)) => {
            tracing::info!(account = %d.account, sessions = d.sessions, profiles = d.profiles.len(), "accounts: account deleted");
            ok(json!({ "deleted": d, "remains": REMAINS }))
        }
        Ok(Err(e)) => account_error(e),
        Err(r) => r,
    }
}

// ---- settings ---------------------------------------------------------------------------------------------------

fn current_settings(a: &Accounts, account: &Account) -> Result<Value, AccountError> {
    Ok(match a.store().settings_doc(&account.id)? {
        Some((version, doc)) => settings::upgrade(version, &doc, &account.display_name),
        None => settings::defaults(&account.display_name),
    })
}

async fn get_settings(State(st): St, h: HeaderMap) -> Response {
    let (account, _) = match authed_limited(&st, &h, Class::Read).await {
        Ok(x) => x,
        Err(r) => return r,
    };
    match blocking(&st, move |a| current_settings(a, &account)).await {
        Ok(Ok(doc)) => ok(json!({ "settings": doc })),
        Ok(Err(e)) => account_error(e),
        Err(r) => r,
    }
}

async fn put_settings(State(st): St, h: HeaderMap, body: Bytes) -> Response {
    let (account, _) = match authed_limited(&st, &h, Class::Write).await {
        Ok(x) => x,
        Err(r) => return r,
    };
    let doc: Value = match parse(&body, settings::MAX_BYTES) {
        Ok(d) => d,
        Err(r) => return r,
    };
    let clean = match settings::validate(&doc, &account.display_name) {
        Ok(c) => c,
        Err(e) => return fail(StatusCode::BAD_REQUEST, "invalid", e),
    };
    let wanted = clean["display_name"].as_str().unwrap_or(&account.display_name).to_string();
    if wanted != account.display_name {
        let hits = moderate::rule_hits(&wanted);
        if !hits.is_empty() {
            return fail(StatusCode::UNPROCESSABLE_ENTITY, "refused", format!("that name is not allowed ({})", hits.join(", ")));
        }
    }
    let res = blocking(&st, move |a| -> Result<Value, AccountError> {
        let mut clean = clean;
        // The name first: if it cannot be taken, nothing is saved.
        let account = if wanted != account.display_name { a.store().rename_account(&account.id, &wanted, None)? } else { account };
        clean["display_name"] = account.display_name.clone().into();
        a.store().put_settings(&account.id, settings::VERSION, &clean)?;
        Ok(clean)
    })
    .await;
    match res {
        Ok(Ok(doc)) => ok(json!({ "settings": doc })),
        Ok(Err(e)) => account_error(e),
        Err(r) => r,
    }
}

// ---- demigods ---------------------------------------------------------------------------------------------------

fn limits() -> Value {
    json!({ "name": moderate::MAX_NAME, "personality": moderate::MAX_PERSONALITY, "style": moderate::MAX_STYLE, "creed": moderate::MAX_CREED })
}

fn default_name(account: &Account, hand: &str) -> String {
    let [l, r] = fn7_plugin::payload::hand_names(&account.display_name);
    if hand == "right" {
        r
    } else {
        l
    }
}

/// A demigod as the routes show it: the text the match uses, the name it will carry, and the moderation record.
fn demigod_view(account: &Account, hand: &str, row: Option<&DemigodRow>) -> Value {
    let doc = row.map(|r| r.r#final.clone()).unwrap_or_default();
    json!({
        "hand": hand,
        "saved": row.is_some(),
        "name": doc.name,
        // What the match calls it: the custom name, else "<display name>'s Left Hand" / "… Right Hand".
        "match_name": doc.name.clone().unwrap_or_else(|| default_name(account, hand)),
        "personality": doc.personality,
        "style": doc.style,
        "creed": doc.creed,
        "moderation": row.map(|r| json!({
            "verdict": r.verdict, "reason": r.reason, "model": r.model, "at": r.moderated_at, "original": r.original,
        })),
    })
}

fn hand_of(raw: &str) -> Result<&'static str, Response> {
    match raw {
        "left" => Ok("left"),
        "right" => Ok("right"),
        _ => Err(fail(StatusCode::NOT_FOUND, "not_found", "the hand is left or right")),
    }
}

async fn get_demigods(State(st): St, h: HeaderMap) -> Response {
    let (account, _) = match authed_limited(&st, &h, Class::Read).await {
        Ok(x) => x,
        Err(r) => return r,
    };
    let res = blocking(&st, move |a| -> Result<Value, AccountError> {
        let (l, r) = (a.store().demigod(&account.id, "left")?, a.store().demigod(&account.id, "right")?);
        Ok(json!({ "left": demigod_view(&account, "left", l.as_ref()), "right": demigod_view(&account, "right", r.as_ref()),
                   "limits": limits() }))
    })
    .await;
    match res {
        Ok(Ok(v)) => ok(v),
        Ok(Err(e)) => account_error(e),
        Err(r) => r,
    }
}

async fn get_demigod(State(st): St, h: HeaderMap, Path(hand): Path<String>) -> Response {
    let (account, _) = match authed_limited(&st, &h, Class::Read).await {
        Ok(x) => x,
        Err(r) => return r,
    };
    let hand = match hand_of(&hand) {
        Ok(h) => h,
        Err(r) => return r,
    };
    match blocking(&st, move |a| a.store().demigod(&account.id, hand).map(|row| demigod_view(&account, hand, row.as_ref()))).await {
        Ok(Ok(v)) => ok(v),
        Ok(Err(e)) => account_error(e),
        Err(r) => r,
    }
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct DemigodBody {
    #[serde(default)]
    name: Option<String>,
    #[serde(default)]
    personality: String,
    #[serde(default)]
    style: String,
    #[serde(default)]
    creed: String,
}

/// Check a field's shape. Text is never altered here: a field that doesn't fit is refused, not trimmed.
fn check_text(label: &str, text: &str, max: usize, multiline: bool) -> Result<(), String> {
    let n = text.chars().count();
    if n > max {
        return Err(format!("{label} is limited to {max} characters (this is {n})"));
    }
    let bad = |c: char| c.is_control() && !(multiline && matches!(c, '\n' | '\r' | '\t'));
    if text.chars().any(bad) {
        return Err(format!("{label} has control characters"));
    }
    Ok(())
}

fn to_sheet(d: &DemigodDoc) -> Sheet {
    Sheet { name: d.name.clone(), personality: d.personality.clone(), style: d.style.clone(), creed: d.creed.clone() }
}

fn to_doc(s: &Sheet) -> DemigodDoc {
    DemigodDoc { name: s.name.clone(), personality: s.personality.clone(), style: s.style.clone(), creed: s.creed.clone() }
}

async fn put_demigod(State(st): St, h: HeaderMap, Path(hand): Path<String>, body: Bytes) -> Response {
    let (account, _) = match authed(&st, &h).await {
        Ok(x) => x,
        Err(r) => return r,
    };
    let hand = match hand_of(&hand) {
        Ok(h) => h,
        Err(r) => return r,
    };
    let b: DemigodBody = match parse(&body, MAX_BODY) {
        Ok(b) => b,
        Err(r) => return r,
    };
    // A name is a label, not prose: surrounding and doubled spaces go (as the match would drop them); an empty one
    // means "no custom name". The three texts are kept exactly as sent.
    let name = b.name.as_deref().map(fn7_plugin::persona::clean_name).filter(|n| !n.is_empty());
    let original = DemigodDoc { name, personality: b.personality, style: b.style, creed: b.creed };
    let checks = [
        check_text("name", original.name.as_deref().unwrap_or(""), moderate::MAX_NAME, false),
        check_text("personality", &original.personality, moderate::MAX_PERSONALITY, true),
        check_text("style", &original.style, moderate::MAX_STYLE, true),
        check_text("creed", &original.creed, moderate::MAX_CREED, true),
    ];
    if let Some(e) = checks.into_iter().find_map(Result::err) {
        return fail(StatusCode::BAD_REQUEST, "invalid", e);
    }
    if original.name.as_deref().is_some_and(|n| !n.chars().any(char::is_alphanumeric)) {
        return fail(StatusCode::BAD_REQUEST, "invalid", "name needs at least one letter or digit");
    }
    // Unchanged since the last save: the stored answer stands, no new pass.
    let (acc, orig) = (account.clone(), original.clone());
    let stored = match blocking(&st, move |a| a.store().demigod(&acc.id, hand)).await {
        Ok(Ok(s)) => s,
        Ok(Err(e)) => return account_error(e),
        Err(r) => return r,
    };
    if let Some(row) = stored.as_ref().filter(|r| r.original == orig) {
        return ok(put_answer(&account, hand, row, &[]));
    }
    if let Err(w) = st.limiter.check(Class::Moderate, &account.id) {
        return limited(w);
    }
    // The lookalike check on the name as written.
    if let Some(n) = original.name.clone() {
        let acc = account.clone();
        match blocking(&st, move |a| a.demigod_name_conflict(&acc, hand, &n)).await {
            Ok(Ok(None)) => {}
            Ok(Ok(Some(why))) => return fail(StatusCode::CONFLICT, "name_conflict", why),
            Ok(Err(e)) => return account_error(e),
            Err(r) => return r,
        }
    }
    // The one moderation pass.
    let mut j = st.moderate(&to_sheet(&original)).await;
    // A rewritten name must pass the lookalike check too; if it cannot, the sheet is refused.
    if j.verdict == Verdict::Rephrase && j.r#final.name != original.name {
        if let Some(n) = j.r#final.name.clone() {
            let acc = account.clone();
            let clash = blocking(&st, move |a| a.demigod_name_conflict(&acc, hand, &n)).await;
            if !matches!(clash, Ok(Ok(None))) {
                j.verdict = Verdict::Refuse;
                j.reason = "The name breaks the content rules and its repair is already taken: please choose another name.".into();
            }
        }
    }
    tracing::info!(account = %account.id, hand, verdict = j.verdict.as_str(), model = %j.model, fallback = ?j.fallback,
                   "accounts: demigod sheet judged");
    let (acc, orig, judged) = (account.clone(), original.clone(), j.clone());
    let res = blocking(&st, move |a| -> Result<Option<DemigodRow>, AccountError> {
        if judged.verdict == Verdict::Refuse {
            a.store().log_refusal(&acc.id, hand, &orig, &judged.reason, &judged.categories, &judged.model)?;
            return Ok(None);
        }
        a.store()
            .put_demigod(&acc.id, hand, &orig, &to_doc(&judged.r#final), judged.verdict.as_str(), &judged.reason, &judged.categories, &judged.model)
            .map(Some)
    })
    .await;
    match res {
        Ok(Ok(Some(row))) => ok(put_answer(&account, hand, &row, &j.categories)),
        Ok(Ok(None)) => finish(
            (
                StatusCode::UNPROCESSABLE_ENTITY,
                Json(json!({
                    "error": "refused", "detail": j.reason, "verdict": "refuse", "reason": j.reason, "categories": j.categories,
                    "model": j.model, "original": original,
                    // Nothing was saved: this is what the account still has.
                    "demigod": demigod_view(&account, hand, stored.as_ref()),
                })),
            )
                .into_response(),
        ),
        Ok(Err(e)) => account_error(e),
        Err(r) => r,
    }
}

/// The `PUT` answer for a saved sheet: `ok` (verbatim) or `rephrase` (with both versions and the reason).
fn put_answer(account: &Account, hand: &str, row: &DemigodRow, categories: &[String]) -> Value {
    let mut v = json!({ "verdict": row.verdict, "model": row.model, "demigod": demigod_view(account, hand, Some(row)) });
    if row.verdict == "rephrase" {
        v["reason"] = row.reason.clone().into();
        v["categories"] = json!(categories);
        v["original"] = json!(row.original);
        v["final"] = json!(row.r#final);
    }
    v
}

// ---- billing (not live) and the game ----------------------------------------------------------------------------

async fn entitlements(State(st): St, h: HeaderMap) -> Response {
    let (account, _) = match authed_limited(&st, &h, Class::Read).await {
        Ok(x) => x,
        Err(r) => return r,
    };
    match blocking(&st, move |a| a.store().entitlements(&account.id)).await {
        Ok(Ok(rows)) => {
            let now = theatre_trace::now_ms();
            let active: Vec<&str> = rows
                .iter()
                .filter(|e| e.status == "active" && e.expires_at.is_none_or(|t| t > now))
                .map(|e| e.sku.as_str())
                .collect();
            ok(json!({
                // Everyone is on the free tier until billing is live; a row would name a paid one.
                "tier": active.first().copied().unwrap_or("free"),
                "entitlements": rows,
                "billing": { "live": false, "provider": null,
                             "note": "Billing is not live: nothing can be bought and no payment provider is called." },
            }))
        }
        Ok(Err(e)) => account_error(e),
        Err(r) => r,
    }
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct BindBody {
    resume_token: String,
}

async fn bind(State(st): St, h: HeaderMap, body: Bytes) -> Response {
    if let Err(w) = st.limiter.check(Class::Auth, &client(&h)) {
        return limited(w);
    }
    let (account, session) = match authed(&st, &h).await {
        Ok(x) => x,
        Err(r) => return r,
    };
    let b: BindBody = match parse(&body, MAX_BODY) {
        Ok(b) => b,
        Err(r) => return r,
    };
    let acc = account.clone();
    let res = blocking(&st, move |a| {
        let player = a.bind(&acc, &session.id, &b.resume_token)?;
        let p = a.seat_persona(&acc.id, 0);
        Ok::<_, &'static str>((player, p))
    })
    .await;
    match res {
        Ok(Ok((player, p))) => ok(json!({
            "bound": true,
            "player_id": player.id,
            "display_name": player.display_name,
            // The names this account's demigods will carry when it takes a seat.
            "demigods": {
                "left": { "match_name": p.left.name.unwrap_or_else(|| default_name(&account, "left")) },
                "right": { "match_name": p.right.name.unwrap_or_else(|| default_name(&account, "right")) },
            },
        })),
        Ok(Err("name_mismatch")) => fail(
            StatusCode::CONFLICT,
            "name_mismatch",
            format!("log in on the websocket as \"{}\" (auth.login display_name), then bind", account.display_name),
        ),
        Ok(Err("not_found")) => fail(StatusCode::NOT_FOUND, "not_found", "no game connection has that resume_token (log in on the websocket first)"),
        Ok(Err(_)) => fail(StatusCode::INTERNAL_SERVER_ERROR, "store", "the account store failed"),
        Err(r) => r,
    }
}

// ---- schemas ----------------------------------------------------------------------------------------------------

/// The JSON Schemas of the account routes' documents: `(file stem, schema)`, written to `docs/schemas/` (a test checks
/// the files are current; `FN7_WRITE_SCHEMAS=1` rewrites them).
pub fn schemas() -> Vec<(&'static str, Value)> {
    let draft = "https://json-schema.org/draft/2020-12/schema";
    let text = |max: usize, d: &str| json!({ "type": "string", "maxLength": max, "description": d });
    let sheet = |d: &str| {
        json!({
            "type": "object", "additionalProperties": false, "description": d,
            "required": ["name", "personality", "style", "creed"],
            "properties": {
                "name": { "type": ["string", "null"], "maxLength": moderate::MAX_NAME, "description": "The custom name, or null." },
                "personality": text(moderate::MAX_PERSONALITY, "The personality text."),
                "style": text(moderate::MAX_STYLE, "The speaking style."),
                "creed": text(moderate::MAX_CREED, "The creed."),
            }
        })
    };
    let demigod = json!({
        "type": "object", "additionalProperties": false,
        "required": ["hand", "saved", "name", "match_name", "personality", "style", "creed", "moderation"],
        "properties": {
            "hand": { "type": "string", "enum": ["left", "right"] },
            "saved": { "type": "boolean", "description": "false until the account saves this demigod (every text is then empty)." },
            "name": { "type": ["string", "null"], "maxLength": moderate::MAX_NAME, "description": "The custom name, or null." },
            "match_name": { "type": "string", "description": "The name the demigod carries in a match: the custom name, else \"<display name>'s Left Hand\" / \"<display name>'s Right Hand\"." },
            "personality": text(moderate::MAX_PERSONALITY, "The personality the match uses."),
            "style": text(moderate::MAX_STYLE, "The speaking style the match uses."),
            "creed": text(moderate::MAX_CREED, "The creed the match uses."),
            "moderation": { "type": ["object", "null"], "additionalProperties": false, "description": "The pass that judged the saved sheet; null until saved.",
                "required": ["verdict", "reason", "model", "at", "original"],
                "properties": {
                    "verdict": { "type": "string", "enum": ["ok", "rephrase"] },
                    "reason": { "type": "string", "description": "Empty for ok." },
                    "model": { "type": "string", "description": "claude-haiku-5-5, or rules when the rules decided." },
                    "at": { "type": "integer", "description": "Epoch ms." },
                    "original": sheet("What the player submitted."),
                } },
        }
    });
    let account = json!({
        "type": "object", "additionalProperties": false,
        "required": ["id", "display_name", "guest", "profile", "identities", "created_at", "updated_at"],
        "properties": {
            "id": { "type": "string", "pattern": "^acc_[0-9a-f]{24}$", "description": "The account's public id. Not a secret." },
            "display_name": { "type": "string", "maxLength": 24, "description": "The name to log in on the websocket with." },
            "guest": { "type": "boolean", "description": "true until a Google identity is linked." },
            "profile": { "type": "string", "description": "The linked profile's key: GET /api/profiles/{profile}." },
            "past_profiles": { "type": "array", "items": { "type": "string" }, "description": "Profiles of names held before a rename. Absent when empty." },
            "identities": { "type": "array", "items": { "type": "object", "additionalProperties": false,
                "required": ["provider", "linked_at"],
                "properties": {
                    "provider": { "type": "string", "enum": ["guest", "google"] },
                    "email": { "type": "string", "description": "The owner's own email (Google). Only ever in the account's own answers." },
                    "email_verified": { "type": "boolean" },
                    "linked_at": { "type": "integer" },
                } } },
            "created_at": { "type": "integer" },
            "updated_at": { "type": "integer" },
        }
    });
    let session = json!({
        "type": "object", "additionalProperties": false,
        "required": ["id", "created_at", "last_seen_at", "expires_at", "device_label", "current"],
        "properties": {
            "id": { "type": "string", "pattern": "^ses_[0-9a-f]{16}$", "description": "Names the session in lists. Not a credential." },
            "created_at": { "type": "integer" }, "last_seen_at": { "type": "integer" },
            "expires_at": { "type": "integer", "description": "Slides to 90 days after each use." },
            "device_label": { "type": "string", "maxLength": 60 },
            "current": { "type": "boolean" },
        }
    });
    let with = |id: &str, title: &str, mut body: Value, defs: Value| {
        body["$schema"] = draft.into();
        body["$id"] = format!("{id}.schema.json").into();
        body["title"] = title.into();
        body["$defs"] = defs;
        body
    };
    let r = |n: &str| json!({ "$ref": format!("#/$defs/{n}") });
    vec![
        ("account_settings", settings::schema()),
        ("account_session", with("account_session", "A new session: POST /api/auth/guest (201) and the complete answer of POST /api/auth/poll",
            json!({ "type": "object", "required": ["session_token", "session", "account"],
                "properties": {
                    "session_token": { "type": "string", "pattern": "^fn7s_[0-9a-f]{64}$", "description": "The credential: Authorization: Bearer <session_token>. Shown once; the server keeps only its hash." },
                    "session": r("Session"), "account": r("Account"),
                    "status": { "const": "complete", "description": "poll only." },
                    "created": { "type": "boolean", "description": "poll only: the account was created by this sign-in." },
                    "linked": { "type": "boolean", "description": "poll only: Google was linked to the account that started the flow (its old session is now revoked)." },
                } }),
            json!({ "Account": account, "Session": session }))),
        ("account_me", with("account_me", "GET /api/me",
            json!({ "type": "object", "additionalProperties": false, "required": ["account", "session", "sessions", "google_configured"],
                "properties": { "account": r("Account"), "session": r("Session"),
                    "sessions": { "type": "array", "items": r("Session"), "description": "The account's live sessions, most recently used first." },
                    "google_configured": { "type": "boolean" } } }),
            json!({ "Account": account, "Session": session }))),
        ("account_demigod", with("account_demigod", "GET /api/me/demigods/{left|right}", demigod.clone(), json!({}))),
        ("account_demigod_put", with("account_demigod_put", "PUT /api/me/demigods/{left|right}: the request",
            json!({ "type": "object", "additionalProperties": false, "description": "Every key optional; a key left out is empty (name: null).",
                "properties": {
                    "name": { "type": ["string", "null"], "maxLength": moderate::MAX_NAME, "description": "Custom name. Surrounding and doubled spaces are dropped; null or \"\" = no custom name." },
                    "personality": text(moderate::MAX_PERSONALITY, "Kept character for character when the verdict is ok. Newlines and tabs allowed; other control characters refused."),
                    "style": text(moderate::MAX_STYLE, "Speaking style."),
                    "creed": text(moderate::MAX_CREED, "A short creed."),
                } }),
            json!({}))),
        ("account_demigod_answer", with("account_demigod_answer", "PUT /api/me/demigods/{left|right}: the moderation answer (200 for ok and rephrase, 422 for refuse)",
            json!({ "type": "object", "required": ["verdict", "model", "demigod"],
                "properties": {
                    "verdict": { "type": "string", "enum": ["ok", "rephrase", "refuse"], "description": "ok: saved exactly as sent. rephrase: saved as `final`; show `original`, `final` and `reason` and let the player edit and send again. refuse (HTTP 422): nothing saved." },
                    "model": { "type": "string", "description": "claude-haiku-5-5, or rules." },
                    "demigod": r("Demigod"),
                    "reason": { "type": "string", "description": "rephrase and refuse: one sentence for the player." },
                    "categories": { "type": "array", "items": { "type": "string", "enum": ["hate", "sexual", "harassment", "instructions", "personal_data"] } },
                    "original": r("Sheet"), "final": r("Sheet"),
                    "error": { "const": "refused", "description": "refuse only." },
                    "detail": { "type": "string", "description": "refuse only: the same text as reason." },
                } }),
            json!({ "Demigod": demigod, "Sheet": sheet("A demigod sheet.") }))),
        ("account_entitlements", with("account_entitlements", "GET /api/me/entitlements (billing is not live)",
            json!({ "type": "object", "additionalProperties": false, "required": ["tier", "entitlements", "billing"],
                "properties": {
                    "tier": { "type": "string", "description": "free, or the sku of an active entitlement." },
                    "entitlements": { "type": "array", "items": { "type": "object", "additionalProperties": false,
                        "required": ["sku", "status", "source", "granted_at"],
                        "properties": { "sku": { "type": "string" }, "status": { "type": "string", "enum": ["active", "past_due", "canceled", "expired"] },
                                        "source": { "type": "string" }, "granted_at": { "type": "integer" }, "expires_at": { "type": "integer" } } } },
                    "billing": { "type": "object", "additionalProperties": false, "required": ["live", "provider", "note"],
                        "properties": { "live": { "const": false }, "provider": { "type": "null" }, "note": { "type": "string" } } },
                } }),
            json!({}))),
        ("account_error", with("account_error", "Every error of the account routes",
            json!({ "type": "object", "required": ["error", "detail"],
                "properties": {
                    "error": { "type": "string", "enum": ["invalid", "bad_name", "unauthorized", "not_found", "name_taken", "name_lookalike",
                        "name_conflict", "name_mismatch", "identity_in_use", "already_linked", "profile_claimed", "confirm_required", "too_large",
                        "refused", "rate_limited", "google_not_configured", "store", "internal"] },
                    "detail": { "type": "string", "description": "Human-readable; switch on error." },
                } }),
            json!({}))),
    ]
}
